/**
 * Simplified browser polyfill for Chrome/Firefox compatibility
 * This is a minimal implementation. For production, download the official webextension-polyfill.
 * Download from: https://cdn.jsdelivr.net/npm/webextension-polyfill@0.12.0/dist/browser-polyfill.min.js
 */

(function() {
  'use strict';

  // If browser is already defined (Firefox), do nothing
  if (typeof browser !== 'undefined' && browser.runtime) {
    return;
  }

  // If chrome is not available, we can't create a polyfill
  if (typeof chrome === 'undefined' || !chrome.runtime) {
    return;
  }

  // Create a simplified browser object that wraps Chrome APIs with Promises
  const wrapAPI = (target) => {
    return new Proxy(target, {
      get(obj, prop) {
        if (!(prop in obj)) {
          return undefined;
        }

        const value = obj[prop];

        if (typeof value === 'function') {
          return function(...args) {
            // Check if the last argument is a callback
            const hasCallback = args.length > 0 && typeof args[args.length - 1] === 'function';

            if (hasCallback) {
              // Use the callback directly
              return value.apply(obj, args);
            } else {
              // Wrap in a Promise
              return new Promise((resolve, reject) => {
                value.call(obj, ...args, (...results) => {
                  if (chrome.runtime.lastError) {
                    reject(new Error(chrome.runtime.lastError.message));
                  } else {
                    resolve(results.length === 1 ? results[0] : results);
                  }
                });
              });
            }
          };
        } else if (typeof value === 'object' && value !== null) {
          return wrapAPI(value);
        } else {
          return value;
        }
      }
    });
  };

  // Create browser object
  window.browser = wrapAPI(chrome);
})();
